<script setup lang="ts">import { reactive } from 'vue';import AppHeader from '../../components/AppHeader.vue';import BottomAction from '../../components/BottomAction.vue';import { useAppStore } from '../../stores/app';import { back } from '../../utils/ui';const store=useAppStore();const form=reactive({title:'',price:'',condition:'九成新',content:'',contact:''});async function submit(){if(!form.title||!form.content||!form.contact)return uni.showToast({title:'请完整填写物品信息',icon:'none'});try{await store.createMarketPost({title:form.title,content:`${form.condition} · ${form.content}`,visibility:'PUBLIC',price:form.price||'面议',contact:form.contact});back()}catch{}}</script>
<template><view class="app-shell no-tabs form-page"><AppHeader title="发布二手" backable/><view class="image-placeholder"><text>图片上传</text><text class="muted">当前 API 未提供可用文件地址时使用统一占位</text></view><view class="field"><text class="field-label">标题</text><input v-model="form.title" class="input" placeholder="品牌、型号或物品名称"/></view><view class="grid-two"><view class="field"><text class="field-label">价格</text><input v-model="form.price" class="input" placeholder="面议"/></view><view class="field"><text class="field-label">成色</text><input v-model="form.condition" class="input"/></view></view><view class="field"><text class="field-label">物品说明</text><textarea v-model="form.content" class="textarea" placeholder="说明使用情况、瑕疵与交易方式"/></view><view class="field"><text class="field-label">联系方式</text><input v-model="form.contact" class="input"/></view><view v-if="store.error" class="notice notice-error">{{ store.error }}</view><BottomAction><button class="btn btn-primary btn-block" @click="submit">发布信息</button></BottomAction></view></template><style scoped>.form-page{padding-bottom:6.5rem}.field{margin-top:1rem}.image-placeholder{display:flex;min-height:8rem;flex-direction:column;align-items:center;justify-content:center;margin-top:1rem;color:#5f6864;background:#e9ece9;border-radius:.875rem;font-size:.875rem;font-weight:700}</style>
